# Try cellular automata - if a cell has >= 2 neighbors of color 1, it becomes 1
def count_neighbors(r, c, grid):
    count = 0
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            if grid[nr][nc] == 1:
                count += 1
    return count

ca_result = []
for r in range(len(grid)):
    row = []
    for c in range(len(grid[0])):
        original = grid[r][c]
        neighbor_count = count_neighbors(r, c, grid)

        if original == 4:
            if neighbor_count >= 4:
                row.append(4)  # become 4
            else:
                row.append(0)  # become 0
        else:  # original == 1
            if neighbor_count >= 2:
                row.append(1)  # stay 1
            else:
                row.append(0)  # become 0
    ca_result.append(row)

print("Cellular automata (>=2 neighbors of 1 -> 1):")
for row in ca_result:
    print(' '.join(map(str, row)))

result = json.dumps({"action": "submit", "grid": ca_result})
print("\n" + result)

